CREATE TABLE public.platform_roles (user_id uuid PRIMARY KEY, role text NOT NULL DEFAULT 'super_admin' CHECK(role='super_admin'));
GRANT SELECT ON public.platform_roles TO authenticated;
GRANT ALL ON public.platform_roles TO service_role;
ALTER TABLE public.platform_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own platform role" ON public.platform_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.is_super_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM platform_roles WHERE user_id=auth.uid() AND role='super_admin') $$;
REVOKE ALL ON FUNCTION public.is_super_admin() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.is_super_admin() TO authenticated,service_role;
CREATE TABLE public.school_subscriptions (school_id uuid PRIMARY KEY REFERENCES public.schools(id) ON DELETE CASCADE, slug text UNIQUE NOT NULL CHECK(slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'), status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended')), subscription_ends_at timestamptz NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.school_subscriptions TO authenticated;
GRANT ALL ON public.school_subscriptions TO service_role;
ALTER TABLE public.school_subscriptions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "subscription read" ON public.school_subscriptions FOR SELECT TO authenticated USING(public.is_super_admin() OR EXISTS(SELECT 1 FROM public.school_members m WHERE m.school_id=school_subscriptions.school_id AND m.user_id=auth.uid() AND m.status='active'));
INSERT INTO public.school_subscriptions(school_id,slug,subscription_ends_at) SELECT id,lower(code),now()+interval '1 year' FROM public.schools;
CREATE FUNCTION public.school_subscription_active(_school uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM school_subscriptions WHERE school_id=_school AND status='active' AND subscription_ends_at>now()) $$;
CREATE OR REPLACE FUNCTION public.member_role(_school uuid) RETURNS public.school_role LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT role FROM public.school_members WHERE school_id=_school AND user_id=auth.uid() AND status='active' AND public.school_subscription_active(_school) LIMIT 1 $$;
DROP POLICY "members read school" ON public.schools;
CREATE POLICY "members read school" ON public.schools FOR SELECT TO authenticated USING(public.is_super_admin() OR EXISTS(SELECT 1 FROM public.school_members m WHERE m.school_id=schools.id AND m.user_id=auth.uid() AND m.status='active'));
CREATE FUNCTION public.provision_managed_school(_name text,_username text,_admin uuid,_slug text,_ends timestamptz,_currency text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _id uuid; _code text; BEGIN IF auth.role()<>'service_role' THEN RAISE EXCEPTION 'Not permitted'; END IF; IF trim(_name)='' OR _ends<=now() OR _currency NOT IN ('USD','ZiG','ZAR') THEN RAISE EXCEPTION 'Invalid school details'; END IF; _code:='SCH-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10)); INSERT INTO schools(code,name,currency,current_year,current_term,created_by) VALUES(_code,trim(_name),_currency,extract(year from current_date)::int,1,_admin) RETURNING id INTO _id; INSERT INTO school_subscriptions(school_id,slug,subscription_ends_at) VALUES(_id,_slug,_ends); INSERT INTO school_members(school_id,user_id,full_name,role,status) VALUES(_id,_admin,_username,'head','active'); INSERT INTO audit_logs(school_id,user_id,action) VALUES(_id,_admin,'school.provisioned'); RETURN _id; END $$;
REVOKE ALL ON FUNCTION public.provision_managed_school(text,text,uuid,text,timestamptz,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.provision_managed_school(text,text,uuid,text,timestamptz,text) TO service_role;
REVOKE EXECUTE ON FUNCTION public.create_school(text,text,text,text,text,integer,integer,text) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.manage_school_subscription(_school uuid,_action text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_super_admin() THEN RAISE EXCEPTION 'Not permitted'; END IF; IF _action IN ('activate','suspend') THEN UPDATE school_subscriptions SET status=CASE WHEN _action='activate' THEN 'active' ELSE 'suspended' END,updated_at=now() WHERE school_id=_school; ELSIF _action IN ('month','term','year') THEN UPDATE school_subscriptions SET subscription_ends_at=greatest(subscription_ends_at,now())+CASE _action WHEN 'month' THEN interval '1 month' WHEN 'term' THEN interval '4 months' ELSE interval '1 year' END,updated_at=now() WHERE school_id=_school; ELSE RAISE EXCEPTION 'Invalid action'; END IF; IF NOT FOUND THEN RAISE EXCEPTION 'School not found'; END IF; INSERT INTO audit_logs(school_id,user_id,action,details) VALUES(_school,auth.uid(),'subscription.updated',jsonb_build_object('action',_action)); END $$;
REVOKE ALL ON FUNCTION public.manage_school_subscription(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.manage_school_subscription(uuid,text) TO authenticated,service_role;
CREATE FUNCTION public.school_gateway(_slug text) RETURNS TABLE(name text,code text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT s.name,s.code FROM schools s JOIN school_subscriptions sub ON sub.school_id=s.id WHERE sub.slug=lower(_slug) LIMIT 1 $$;
REVOKE ALL ON FUNCTION public.school_gateway(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.school_gateway(text) TO anon,authenticated,service_role;